    if (border != 0) {
        return;
    }

    // Adjust source rectangle if needed
    GLint source_width = source_image_rect.width;
    GLint source_height = source_image_rect.height;
    GLint source_x = source_image_rect.x;
    GLint source_y = source_image_rect.y;

    if (function_id == TEXTURE_3D) {
        glTexSubImage3D(target, level, xoffset, yoffset, zoffset,
