    }
}

void uploadTexImage(
    TexImageFunctionID function_id,
    GLenum target,
    GLint level,
    GLint internalformat,
    GLint border,
    GLenum format,
    GLenum type,
    GLsizei depth,
    GLint xoffset,
    GLint yoffset,
    GLint zoffset,
    ImageData* pixels,
    const IntRect* source_image_rect,
    GLint unpack_image_height
) {
    // Validate the border parameter
    if (border != 0) {
        // WebGL requires border to be 0
        return;
    }

    // Check if the context is valid and active
    if (!pixels || !source_image_rect) {
        // Invalid input data
        return;
    }

    // Adjust the source rectangle if necessary
    GLint width = source_image_rect->x2 - source_image_rect->x1;
    GLint height = source_image_rect->y2 - source_image_rect->y1;

    if (width <= 0 || height <= 0) {
        // Invalid rectangle dimensions
        return;
    }

    // Set the unpack image height if provided
    if (unpack_image_height > 0) {
        glPixelStorei(GL_UNPACK_IMAGE_HEIGHT, unpack_image_height);
    }

    // Upload to 3D texture if depth > 0 and appropriate function
    if (function_id == TEXTURE_3D) {
        glTexImage3D(
            target,
            level,
            internalformat,
            width + xoffset,
            height + yoffset,
            depth + zoffset,
            border,
            format,
            type,
            pixels->data
        );
    } else {
        // Assume 2D texture
        glTexImage2D(
            target,
            level,
            internalformat,
            width + xoffset,
            height + yoffset,
            border,
            format,
            type,
            pixels->data
        );
    }
}

void upload_image_to_texture(TextureImageFunctionID function_id, GLenum target, GLint level,
                             GLint internalformat, GLint border, GLenum format, GLenum type,
                             GLsizei depth, GLint xoffset, GLint yoffset, GLint zoffset,
                             ImageData* pixels, const IntRect* source_image_rect, GLint unpack_image_height) {
    if (!pixels || !pixels->data || !pixels->width || !pixels->height) {
        return;
    }

    // Validate border (must be zero)
    if (border != 0) {
        return;
    }

    // Validate source rectangle and adjust if necessary
    GLint src_x = source_image_rect->x;
    GLint src_y = source_image_rect->y;
    GLsizei src_width = source_image_rect->width;
    GLsizei src_height = source_image_rect->height;

    if (src_x < 0 || src_y < 0 || src_width < 0 || src_height < 0) {
        return;
    }

    GLint x_start = xoffset + src_x;
    GLint y_start = yoffset + src_y;

    // Calculate effective width and height, based on source rectangle and target texture dimensions
    GLsizei effective_width = src_width;
    GLsizei effective_height = src_height;

    // Set unpack parameters if needed
    if (unpack_image_height > 0) {
        glPixelStorei(GL_UNPACK_IMAGE_HEIGHT, unpack_image_height);
    }

    // Determine which WebGL function to call based on the function_id
    if (function_id == TEX_IMAGE_2D) {
        glTexImage2D(target, level, internalformat, effective_width, effective_height, border,
                     format, type, pixels->data);
    }
    else if (function_id == TEX_SUB_IMAGE_2D) {
        glTexSubImage2D(target, level, x_start, y_start, effective_width, effective_height,
                        format, type, pixels->data);
    }
    else if (function_id == TEX_SUB_IMAGE_3D) {
        glTexSubImage3D(target, level, x_start, y_start, zoffset, effective_width,
                        effective_height, depth, format, type, pixels->data);
    }
}

