void uploadTexImage(
    TexImageFunctionID function_id,
    GLenum target,
    GLint level,
    GLint internalformat,
    GLint border,
    GLenum format,
    GLenum type,
    GLsizei depth,
    GLint xoffset,
    GLint yoffset,
    GLint zoffset,
    ImageData* pixels,
    const IntRect* source_image_rect,
    GLint unpack_image_height)
{
    // Validate that the border is zero as required
    if (border != 0) {
        // In WebGL, border must be zero, so fail if not
        return;
    }

    // Check if context is valid (assumed to be a global or accessible)
    if (!is_context_valid()) {
        return;
    }

    // Adjust the source rectangle if needed
    IntRect adjusted_rect = *source_image_rect;
    if (adjusted_rect.width <= 0 || adjusted_rect.height <= 0) {
        // Invalid or zero-area source image; no upload
        return;
    }

    // Set the unpack image height if provided
    if (unpack_image_height > 0) {
        glPixelStorei(GL_UNPACK_IMAGE_HEIGHT, unpack_image_height);
    }

    // Determine which function to call based on function_id
    switch (function_id) {
        case TEXTURE_2D:
            // Call glTexImage2D with the provided parameters and adjusted source rectangle
            glTexImage2D(
                target,
                level,
                internalformat,
                adjusted_rect.width,
                adjusted_rect.height,
                border,
                format,
                type,
                pixels->data);
            break;
        case TEXTURE_3D:
            glTexSubImage3D(
                target,
                level,
                xoffset,
                yoffset,
                zoffset,
                adjusted_rect.width,
                adjusted_rect.height,
                depth,
                format,
                type,
                pixels->data);
            break;
        default:
            // Unsupported function ID
            return;
    }
}
